    def bt_frameMoradores_print(self):
              
        page_width, page_height = A4
        margin = 2 * cm
        text_y_position = page_height - margin  # Início do texto no topo da página
        line_height = 20  # Altura da linha de texto em pontos (ajuste conforme necessário)
        max_y_position = margin  # Limite inferior da página

        timestamp = time.strftime("%d%m%Y-%H%M%S")
        save_path = filedialog.asksaveasfilename(initialfile=("Moradores-%s.pdf" % timestamp),defaultextension=".pdf", filetypes=[("PDF files", "*.pdf")])
        if save_path:
           
            self.pdf = canvas.Canvas(save_path, pagesize=A4)
            self.pdf.setTitle('lista de Moradores')
       
        self.pdf.setFont("Helvetica-Bold", 24)
        self.pdf.drawCentredString((page_width/2), text_y_position, 'Ficha do Cliente') # titulo

        self.pdf.setFont("Helvetica-Bold", 18)
        
        self.pdf.drawString(margin,750, 'Nome: ')
        self.pdf.drawString(350,750, 'Telefone: ')
       
        lista = self.listaMoradores.get_children()
                       
        text_y_position=720
        for i in lista:

            values = self.listaMoradores.item(i, 'values')

            if text_y_position <= max_y_position:
                self.pdf.showPage()  # Gera nova página
                text_y_position = page_height - margin  # Reseta posição para o topo da nova página
                       
            self.pdf.setFont("Helvetica", 14)
            self.pdf.drawString(margin, text_y_position, values[2])
                        
            self.pdf.drawString(350,text_y_position, values[6])

            text_y_position -= line_height  # Move para a próxima linha
           
        self.pdf.showPage()
        self.pdf.save()
        webbrowser.open(save_path)
