    def bt_frameUsuarios_print(self):
        page_width, page_height = A4
        margin = 2 * cm
        text_y_position = page_height - margin
        line_height = 20
        max_y_position = margin

        timestamp = time.strftime("%d%m%Y-%H%M%S")
        save_path = filedialog.asksaveasfilename(initialfile=("Usuarios-%s.pdf" % timestamp),defaultextension=".pdf", filetypes=[("PDF files", "*.pdf")])
        if save_path:
            self.pdf = canvas.Canvas(save_path, pagesize=A4)
            self.pdf.setTitle('lista de Usuarios')

        self.pdf.setFont("Helvetica-Bold", 24)
        self.pdf.drawCentredString((page_width/2), text_y_position, 'Ficha do Usuario')

        self.pdf.setFont("Helvetica-Bold", 18)

        self.pdf.drawString(margin,750, 'Nome: ')
        self.pdf.drawString(350,750, 'Telefone: ')  
        lista = self.listaUsuarios.get_children()
        text_y_position=720
        for i in lista:
            values = self.listaUsuarios.item(i, 'values')
            if text_y_position <= max_y_position:
                self.pdf.showPage()
                text_y_position = page_height - margin
            self.pdf.setFont("Helvetica", 14)
            self.pdf.drawString(margin, text_y_position, values[1])
            self.pdf.drawString(350,text_y_position, values[4])
            text_y_position -= line_height  
        self.pdf.showPage()
        self.pdf.save()
        webbrowser.open(save_path)

