        print(nome)
        self.cursor.execute(
            """  SELECT id,nome, descricao, professor_responsavel, dias_semana, horario_inicio,horario_termino,local, numero_vagas FROM aulas
            WHERE descricao LIKE '%s' ORDER BY descricao COLLATE NOCASE ASC""" % nome)
